"""Generate a self-contained design sheet. Not application code or an interaction prototype."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
REPO = ROOT.parents[2]
palettes = json.loads((ROOT / 'palette-proposal.json').read_text())
world = json.loads((REPO / 'frontend/src/native-ranges/data/world-110m.json').read_text())
paths = ''.join(f'<path d="{html.escape(path)}"/>' for path in world['units'].values())
icons = {
    'search': '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
    'filter': '<path d="M3 4h18l-7 8v7l-4 2v-9Z"/>',
    'saved': '<path d="M6 3h12v18l-6-4-6 4Z M9 7h6 M9 10h6"/>',
    'add': '<path d="M12 4v16M4 12h16"/>',
    'edit': '<path d="m4 15 11-11 5 5L9 20l-6 1Z M13 6l5 5"/>',
    'more': '<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
    'back': '<path d="m10 5-7 7 7 7M3 12h18"/>',
    'settings': '<path d="m9 3-1 3-3 1-2 3 2 2-1 3 3 2 3-1 2 2 3-2 1-3 3-1-1-4-3-1-1-3Z"/><circle cx="12" cy="11" r="3"/>',
    'theme': '<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M12 16v5M8 21h8"/>',
    'close': '<path d="m6 6 12 12M6 18 18 6"/>',
    'print': '<path d="M6 8V3h12v5M6 17H3V9h18v8h-3M6 14h12v7H6Z"/>',
    'refresh': '<path d="M20 10a8 8 0 1 0-1 8M20 4v6h-6"/>',
    'layers': '<path d="m2 8 10-5 10 5-10 5Zm0 5 10 5 10-5M2 18l10 5 10-5"/>',
    'download': '<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
    'clear': '<rect x="3" y="3" width="18" height="18" rx="2"/><path d="m8 8 8 8m-8 0 8-8"/>',
    'expand': '<path d="m5 9 7 7 7-7"/>',
}
def icon(name):
    return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">'+icons[name]+'</svg>'
def button(label, name=None, kind='secondary'):
    return f'<span class="action {kind}">'+(icon(name) if name else '')+f'<span>{label}</span></span>'
def search(label):
    return '<div class="search">'+icon('search')+'<span>'+label+'</span></div>'
def header(eyebrow,title,tools=''):
    return f'<header class="page-header"><div><p class="eyebrow">{eyebrow}</p><h2>{title}</h2></div><div class="tools">{tools}</div></header>'
def directory(title,query,creation,count='1'):
    return header('Collection' if title=='Seeds' else 'Sourcing' if title=='Orders' else 'Explore',title,
        search(query)+button('Filters'+(' ('+count+')' if count else ''),'filter')+button('Saved views','saved')+button(creation,'add','primary'))
seeds=directory('Seeds','Search lots, identity or location','New seed lot')+'''<p class="chip">Lifecycle: Active ×</p><div class="directory"><div class="rows"><div class="row selected"><strong><i>Ocimum basilicum</i> · Genovese</strong><span>Seed lot · Active · Quantity unknown</span></div><div class="row"><strong><i>Salvia officinalis</i></strong><span>Seed lot · Active · Greenhouse</span></div><div class="row"><strong><i>Lavandula angustifolia</i></strong><span>Seed lot · Active · Location unknown</span></div></div><aside><p class="eyebrow">Quick preview</p><h3><i>Ocimum basilicum</i></h3><p>Genovese · Seed lot</p><p class="muted">Quantity unknown</p><div class="tools">'''+button('Details')+button('Edit','edit')+'''</div></aside></div>'''
identities=directory('Botanical identities','Search botanical identities','New botanical identity','')+'<p class="muted">Existing collection scope and identity filters remain in the filter drawer.</p>'
orders=directory('Orders','Reference, Supplier or notes','New Order')+'<p class="chip">Supplier: Alpine Botanical Exchange ×</p><div class="row"><strong>Autumn seed order</strong><span>Order date: October 2026 · Total unknown</span></div>'
map_svg='<svg class="map" viewBox="0 0 720 360" role="img" aria-label="Unselected local geography design specimen"><g fill="var(--border)" stroke="var(--border-strong)" stroke-width="0.25">'+paths+'</g></svg>'
origins=header('Explore','Collection origins',button('Manage provenance sites'))+'<div class="tools">'+button('Saved views','saved')+'</div><div class="inline-filters"><strong>Filter linked collection records</strong><div class="tools"><span>☑ SeedLots</span><span>☑ Plants and PlantGroups</span>'+search('Botanical identity')+'</div></div><div class="map-layout"><div>'+map_svg+'<p class="muted">Local geography specimen · Natural Earth, public domain. Production basemap attribution remains visible.</p></div><aside><h3>Mapped provenance sites</h3><p>Recorded provenance only</p><p class="muted">Map/list selection and accuracy semantics unchanged.</p></aside></div>'
detail=header('Seed lot','Ocimum basilicum · Genovese',button('Back to Seeds','back')+button('Edit','edit')+button('More','more'))+'<div class="detail"><section><h3>Overview</h3><div class="fact"><span>Botanical identity</span><strong><i>Ocimum basilicum</i></strong></div><div class="fact"><span>Quantity</span><strong>Unknown</strong></div><div class="fact"><span>Location</span><strong>Unknown</strong></div></section><section><h3>Related work</h3><p>No recorded Sowings</p>'+button('Record Sowing',None,'primary')+'</section></div>'
nav='<div class="desktop-nav"><strong>Overview · Collection · Activity · Explore · Sourcing</strong><div class="tools">'+button('Settings','settings')+button('Appearance','theme')+button('Sign out',None,'quiet')+'</div></div><div class="phone-nav"><span>Home</span><span class="active">Seeds</span><span>Sowings</span><span>Plants</span><span>More</span></div><div class="more-panel"><h3>More navigation</h3><p>Activity · Explore · Sourcing</p><div class="tools">'+button('Settings','settings')+button('Appearance','theme')+button('Sign out',None,'quiet')+'</div></div>'
form=header('Seed lot','Edit seed lot')+'<div class="form"><h3>Identity and inventory</h3><div class="field-grid"><div><label>Botanical identity</label><div class="field-value"><i>Ocimum basilicum</i></div></div><div><label>Operator label</label><div class="field-value">Genovese</div></div><div><label>Quantity</label><div class="field-value">Unknown</div></div><div><label>Location</label><div class="field-value">Not recorded</div></div></div><div class="tools">'+button('Cancel')+button('Save changes',None,'primary')+'</div></div><div class="modal-stage"><div class="modal"><h3>Discard unsaved changes?</h3><p>Your edits have not been saved.</p><div class="tools">'+button('Keep editing')+button('Discard changes',None,'danger')+'</div></div></div>'
map_workspace=header('Explore','Native ranges',button('Filters','filter')+button('Saved views','saved'))+'<div class="tools">'+button('Species comparison')+button('Clear selection','clear')+'</div><div class="map-layout"><div>'+map_svg+'</div><aside><h3>Comparison key</h3>'+''.join(f'<p class="legend"><span style="background:var(--series-{i})"></span>{i} · {n}</p>' for i,n in enumerate(['Ocimum basilicum','Salvia officinalis','Lavandula angustifolia','Thymus vulgaris','Rosmarinus officinalis'],1))+'<p class="muted">Unselected geography: no fabricated distribution. Same five identity slots in every theme.</p></aside></div><p class="muted">Structured botanical reference geography · Natural Earth local geometry.</p>'
settings=header('Application','Settings')+'<h3>Appearance</h3><p class="muted">Applies to this browser</p><div class="palette-choices">'+''.join('<div class="palette-choice" data-palette="'+n.split()[0]+'"><span class="swatches" style="background:'+t['background']+';border-color:'+t['primary']+';color:'+t['text']+'">Aa <b style="color:'+t['primary']+'">●</b></span>'+n.split()[0]+'<span class="choice-marker"></span></div>' for n,t in palettes.items() if n.endswith('Light'))+'</div><div class="tools">'+button('◉ System')+button('Light')+button('Dark')+'</div><p class="muted"><span id="effective-mode">System</span></p><hr><div class="tools">'+button('Settings','settings')+button('Appearance','theme')+'</div>'
patterns='<h3>Shared action vocabulary</h3><div class="tools">'+''.join(button(n.replace('-',' ').title(),n) for n in icons)+'</div><hr><h3>Action hierarchy and tooltip specimen</h3><div class="tools">'+button('More','more')+button('Edit','edit')+button('Save changes',None,'primary')+button('Delete seed lot',None,'danger')+'</div><div class="tooltip-row"><span class="action focus">'+icon('more')+'</span><span class="tooltip">More actions</span><span class="muted">Fine-pointer icon-only trigger; focus stays on button. Touch keeps “More”.</span></div>'
sections=[('01 · Seeds directory and Quick Preview',seeds),('02 · Botanical identities toolbar',identities),('03 · Orders toolbar',orders),('04 · Collection origins toolbar and layout',origins),('05 · Detail page actions',detail),('06 · Navigation: existing desktop and phone destinations',nav),('07 · Create/Edit and modal structure',form),('08 · Map workspace and five-species legend',map_workspace),('09 · Settings and footer chooser',settings),('10 · Icons, hierarchy and tooltip appearance',patterns)]
css='''
*{box-sizing:border-box}body{margin:0;font:15px/1.4667 "Source Sans 3 Variable","Source Sans 3",system-ui,sans-serif;background:#ebeeeb;color:#1e2621}.review-bar{padding:16px 24px;background:#fff;border-bottom:1px solid #7c8980}.review-bar h1{font-size:22px;margin:0 0 8px}.review-bar p{max-width:85ch;margin:8px 0}.review-bar label{display:inline-flex;gap:8px;align-items:center;margin-right:16px}.review-bar select{font:inherit;padding:8px;min-height:44px}.review-bar a{color:#24533e}main{overflow:auto;padding:24px}.sheet{width:1440px;margin:auto;background:var(--background);color:var(--text);padding:24px;container-type:inline-size}.sheet[data-width="1024"]{width:1024px}.sheet[data-width="390"]{width:390px;padding:16px}.specimen{padding:24px 0;border-bottom:1px solid var(--border-strong)}.specimen:first-child{padding-top:0}.caption{font-size:13px;color:var(--text-muted);margin:0 0 16px}.page-header{display:flex;align-items:center;gap:24px;flex-wrap:wrap;margin-bottom:16px}.page-header>div:first-child{flex:1 1 240px}.page-header>.tools{flex:2 1 560px;justify-content:flex-end}.eyebrow{font-size:11px;letter-spacing:.08em;text-transform:uppercase;font-weight:650;color:var(--text-muted);margin:0 0 4px}h2{font-size:32px;line-height:1.1875;font-weight:650;margin:0}h3{font-size:17px;margin:0 0 12px;font-weight:650}p{margin:8px 0 16px}.tools{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.action{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;min-width:44px;padding:8px 12px;border:1px solid var(--border-strong);border-radius:6px;background:var(--surface);color:var(--text);font-weight:600;max-width:100%;overflow-wrap:anywhere}.primary{background:var(--primary);border-color:var(--primary);color:var(--on-primary)}.danger{border-color:var(--danger);color:var(--danger)}.quiet{background:transparent;border-color:transparent;color:var(--primary)}.icon{width:18px;height:18px;flex:none}.search{flex:1 1 224px;display:flex;align-items:center;gap:8px;min-height:44px;padding:8px 12px;border:1px solid var(--border-strong);border-radius:6px;background:var(--surface);color:var(--text-muted);min-width:0}.search span{overflow-wrap:anywhere}.chip{display:inline-block;background:var(--primary-subtle);padding:8px 12px;border-radius:6px;color:var(--primary);margin:0 0 12px}.directory{display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,1fr);gap:24px}.rows{background:var(--surface);border:1px solid var(--border);border-radius:10px}.row{padding:12px 16px;border-bottom:1px solid var(--border);display:flex;flex-direction:column;gap:4px}.row span,.muted{color:var(--text-muted)}.selected{background:var(--primary-subtle);box-shadow:inset 3px 0 var(--primary)}aside{padding:16px;background:var(--surface);border:1px solid var(--border);border-radius:10px}i{font-family:"Source Serif 4 Variable","Source Serif 4",Georgia,serif} .inline-filters{margin:16px 0;padding:16px 0;border-block:1px solid var(--border)}.inline-filters>strong{display:block;margin-bottom:8px}.map-layout{display:grid;grid-template-columns:minmax(0,3fr) minmax(230px,1fr);gap:24px}.map{display:block;width:100%;height:auto;background:var(--surface);border:1px solid var(--border)}.detail{display:grid;grid-template-columns:2fr 1fr;gap:24px}.detail section,.form{background:var(--surface);padding:16px;border:1px solid var(--border);border-radius:10px}.fact{display:flex;justify-content:space-between;flex-wrap:wrap;gap:16px;padding:12px 0;border-bottom:1px solid var(--border)}.desktop-nav{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;padding:16px;background:var(--surface-subtle)}.phone-nav{display:none}.more-panel{margin-top:16px;padding:16px;border:1px solid var(--border);background:var(--surface)}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:24px}.field-grid label{display:block;font-weight:600;margin-bottom:4px}.field-value{background:var(--surface);border:1px solid var(--border-strong);padding:12px;border-radius:6px}.modal-stage{margin-top:24px;padding:32px;background:var(--overlay-backdrop)}.modal{margin:auto;max-width:460px;background:var(--surface);padding:24px;border:1px solid var(--border-strong);border-radius:10px;box-shadow:var(--elevation-overlay)}.legend{display:flex;gap:8px;align-items:center}.legend>span{display:block;min-width:16px;height:16px;border:1px solid var(--border-strong)}.palette-choices{display:flex;flex-wrap:wrap;gap:16px;margin:16px 0}.palette-choice{display:flex;flex-direction:column;gap:8px;min-width:100px}.swatches{border:2px solid;padding:12px;border-radius:6px;font-size:22px}.tooltip-row{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin:24px 0 8px}.focus{outline:3px solid var(--focus-ring);outline-offset:3px}.tooltip{padding:8px 12px;background:var(--surface);color:var(--text);border:1px solid var(--border-strong);border-radius:6px;box-shadow:var(--elevation-overlay);font-size:13px}hr{border:0;border-top:1px solid var(--border);margin:24px 0}.active{border-bottom:3px solid var(--primary)}
@container(max-width:1000px){.page-header>.tools{flex-basis:100%;justify-content:flex-start}.detail{grid-template-columns:1fr}.map-layout{grid-template-columns:1fr}.map-layout aside{border-radius:6px}.directory{grid-template-columns:minmax(0,2fr) minmax(230px,1fr)}}
@container(max-width:600px){.page-header{gap:12px}.page-header>.tools{flex-basis:100%}.search{flex-basis:100%}.directory,.field-grid{grid-template-columns:1fr}.modal-stage{padding:16px}.modal{padding:16px}.desktop-nav{display:none}.phone-nav{display:flex;gap:4px;justify-content:space-between;background:var(--surface);border-top:1px solid var(--border-strong)}.phone-nav>span{min-height:44px;padding:12px 3px;font-size:13px}.specimen{padding:24px 0}.fact{gap:8px}.action{white-space:normal}.map-layout{gap:16px}}
'''
blocks=''.join(f'<section class="specimen"><p class="caption">{caption}</p>{body}</section>' for caption,body in sections)
output='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Florabase themes and controls — design review</title><style>'+css+'</style></head><body><div class="review-bar"><h1>Florabase · Themes and controls design review</h1><p>Static design specimens, not application screenshots or working product controls. Review selectors below change only this sheet. Six variants × three widths; scroll horizontally for a larger sheet. No requests or persistence.</p><label>Variant <select id="variant">'+''.join('<option>'+n+'</option>' for n in palettes)+'</select></label><label>Viewport width <select id="width"><option>1440</option><option>1024</option><option>390</option></select></label><p>Panels are content-area excerpts; full app viewport height target is 844px. Existing typography scale is retained; bundled fonts are not copied, so local fallback may differ. Map geometry is repository Natural Earth data, with no fabricated evidence fills.</p></div><main><article class="sheet" id="sheet" data-width="1440">'+blocks+'</article></main><script>const palettes='+json.dumps(palettes)+';const sheet=document.getElementById("sheet");function update(){const name=document.getElementById("variant").value;const t=palettes[name];for(const [k,v] of Object.entries(t)){if(typeof v==="string")sheet.style.setProperty("--"+k,v)}t.comparison.forEach((c,i)=>sheet.style.setProperty("--series-"+(i+1),c));sheet.dataset.width=document.getElementById("width").value;sheet.setAttribute("aria-label",name+" design specimens");document.getElementById("effective-mode").textContent="System · currently "+name.split(" ")[1]+" (example)";document.querySelectorAll(".palette-choice").forEach(e=>{e.querySelector(".choice-marker").textContent=e.dataset.palette===name.split(" ")[0]?"✓ Selected":"";const v=palettes[e.dataset.palette+" "+name.split(" ")[1]];const sw=e.querySelector(".swatches");sw.style.background=v.background;sw.style.color=v.text;sw.style.borderColor=v.primary;sw.querySelector("b").style.color=v.primary})}document.getElementById("variant").addEventListener("change",update);document.getElementById("width").addEventListener("change",update);update();</script></body></html>'
(ROOT/'review.html').write_text(output)
print(f'Review artifact: {len(output)} bytes, {len(sections)} specimens, 18 variant/width combinations')
